class Solution:

	def util(self, a, i, j, n, m):
		global dp
		if i >= n or i < 0 or j >= m or (j < 0):
			return 0
		if dp[i][j] != -1:
			return dp[i][j]
		dp[i][j] = a[i][j] + max(self.util(a, i + 1, j, n, m), max(self.util(a, i + 1, j + 1, n, m), self.util(a, i + 1, j - 1, n, m)))
		return dp[i][j]

	def maximumPath(self, N, Matrix):
		ans = 0
		global dp
		dp = [[-1 for i in range(N)] for j in range(N)]
		for i in range(N):
			ans = max(ans, self.util(Matrix, 0, i, N, N))
		return ans
